"""Text templates embedded from the full Tobias Holzmann case."""

FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated during November 2017\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 10 Februar 2025\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Building a 2D AMI mesh using baffles and snappyHexMesh\n\nNote: Since v12, the case changed since open.cfd does not support the mesh\nmotion as in previous versions. A quick fix was to start with negative start\ntime and there might be a potential bug since saving the time zero. Therefore\na short quick-and-dirty fix was added (output given).${NC}\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"`\n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "     Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    '0.orig/S': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      binary;\n    class       volScalarField;\n    location    "0";\n    object      S;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 0 0 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    inlet\n    {\n        type            fixedValue;\n        value           uniform 1;\n    }\n\n    outlet \n    {\n        type            inletOutlet;\n        inletValue      uniform 0;\n        value           uniform 0;\n    }\n\n    pipe\n    {\n        type            zeroGradient;\n    }\n\n    innerWall \n    {\n        type            zeroGradient;\n    }\n\n    outerWall \n    {\n        type            zeroGradient;\n    }\n\n    AMI1\n    {\n        type            zeroGradient;\n    }\n\n    AMI2\n    {\n        type            zeroGradient;\n    }\n\n    front\n    {\n        type            empty;\n    }\n\n    back \n    {\n        type            empty;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/U': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volVectorField;\n    object      U;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -1 0 0 0 0];\n\ninternalField   uniform (0 0 0);\n\nboundaryField\n{\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    inlet \n    {\n        type            surfaceNormalFixedValue;\n        refValue        uniform -0.2;\n        value           uniform (0 0 0);\n    }\n\n    outlet \n    {\n        type            inletOutlet;\n        inletValue      uniform (0 0 0);\n        value           uniform (0 0 0);\n    }\n\n    innerWall \n    {\n        type            noSlip;\n    }\n\n    outerWall \n    {\n        type            noSlip;\n    }\n\n    pipe    \n    {\n        type            movingWallVelocity;\n        value           uniform (0 0 0);\n    }\n\n    AMI1\n    {\n        //type            movingWallSlipVelocity;\n        //value           uniform (0 0 0);\n        type            zeroGradient\n    }\n\n    AMI2\n    {\n        //type            movingWallSlipVelocity;\n        //value           uniform (0 0 0);\n        type            zeroGradient;\n    }\n\n    front\n    {\n        type            empty;\n    }\n\n    back \n    {\n        type            empty;\n    }\n}\n\n// ************************************************************************* //\n',
    '0.orig/p': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      binary;\n    class       volScalarField;\n    location    "0";\n    object      p;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -2 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    #includeEtc "caseDicts/setConstraintTypes"\n\n    inlet \n    {\n        type            zeroGradient;\n    }\n\n    pipe\n    {\n        type            zeroGradient;\n    }\n\n    outlet \n    {\n        type            fixedValue;\n        value           uniform 0;\n    }\n\n    innerWall \n    {\n        type            zeroGradient;\n    }\n\n    outerWall \n    {\n        type            zeroGradient;\n    }\n\n    AMI1\n    {\n        type            zeroGradient;\n    }\n\n    AMI2\n    {\n        type            zeroGradient;\n    }\n\n    front\n    {\n        type            empty;\n    }\n\n    back \n    {\n        type            empty;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: April 2016                      #\n# Topic:                                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -rf 0 log* constant/dynamicMeshDict\n\n\n#-------------------------------------------------------------------------------\n',
    'constant/.dynamicMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      dynamicMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nmover\n{\n    type                motionSolver;\n    libs                ("libfvMotionSolvers.so");\n\n    motionSolver            solidBody;\n    solidBodyMotionFunction rotatingMotion;\n\n    cellZone    rotatingCells;\n    origin      (0 0 0);\n    axis        (0 0 1);\n    omega       0.8;\n}\n\n// ************************************************************************* //\n',
    'constant/momentumTransport': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      momentumTransport;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsimulationType laminar;\n\n\n// ************************************************************************* //\n',
    'constant/transportProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      transportProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ntransportModel  Newtonian;\n\nnu              [0 2 -1 0 0 0 0] 1e-5;\n\n// ************************************************************************* //\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------# Contributor: Tobias Holzmann                    #\n# Updated on:  26 Januar 2025                     #\n# Updated on:  10 Februar 2025                    #\n# Topic:       2D AMI generation using baffles    #\n# OpenFOAM:    version 12 (Foundation)            #\n# OpenFOAM:    version 12 (Foundation)            #\n# Website:     https://Holzmann-cfd.com           #\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n\n\n#------------------------------------------------------------------------------\nif [ -f cad/backgroundMesh.unv ];\nthen\n    echo "   - Background mesh exist, proceed..."\nelse\n    echo "   - No background mesh exist, please create one\'"\n    echo ""\n    exit\nfi\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create background mesh"\nideasUnvToFoam cad/backgroundMesh.unv > logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Meshing with snappyHexMesh (~ 80 seconds)"\nsnappyHexMesh -overwrite >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Change the patch type to empty of front and empty"\nchangeDictionary >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Flatten front and back site"\nflattenMesh >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Build a 2D mesh"\nextrudeMesh >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Cleaning"\nrm constant/polyMesh/*Zones constant/polyMesh/*Level* constant/polyMesh/level* \\\n    0 -rf\n\n\n#------------------------------------------------------------------------------\necho -e "   - Building the cellZones in 2D"\ntopoSet >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create Baffles for AMI and the pipe wall"\ncreateBaffles -overwrite >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Split baffles"\nsplitBaffles -overwrite >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create nonConformal patches"\ncreateNonConformalCouples -overwrite AMI1 AMI2 >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\n"\n\n#------------------------------------------------------------------------------\necho -e "   - Copy 0.orig to 0"\nrm -rf 0 -- -4\ncp -r -- 0.orig -4\n\n\n#------------------------------------------------------------------------------\necho -e "   - Start simulation"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Renumber mesh for speedup (~5-15%)"\nrenumberMesh -overwrite > logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Start transient calculation without rotation (a few minutes)"\necho -e "     Since v12, we cannot set the time for rotation start anymore"\necho -e "     Thus, we start at -4s to 0s init the passive scalar field"\nfoamDictionary system/controlDict -entry startTime -set -4 >> logSolver\nfoamDictionary system/controlDict -entry endTime -set 0.025 >> logSolver\nfoamRun >> logSolver\n\n\n#------------------------------------------------------------------------------\n# Workaround for v12 since we start at -4 s, time 0 is not reached perfectly\n# Thus we go to 0.025 and rename it to be 0\necho -e "   - Quick and dirty fix for v12"\nmv 0.025 0\nrm -r 0/uniform\n\n\n#------------------------------------------------------------------------------\necho -e "   - Start rotation (approx one hour)"\necho -e "     Run time increased due to conservative NCC (> 20 %)"\nfoamDictionary system/controlDict -entry startTime -set 0 >> logSolver\nfoamDictionary system/controlDict -entry endTime -set 6 >> logSolver\ncp constant/.dynamicMeshDict constant/dynamicMeshDict\nfoamRun >> logSolver\n\n\n#------------------------------------------------------------------------------\necho -e "   - Simulation ended\\n\\n"\n\n\n#------------------------------------------------------------------------------\n',
    'system/changeDictionaryDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      changeDictionaryDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nboundary\n{\n    front \n    {\n        type        empty;\n    }\n    back\n    {\n        type        empty;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version         2;\n    format          ascii;\n    class           dictionary;\n    object          controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     foamRun;\n\nsolver          incompressibleFluid;\n\nstartFrom       startTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         6;\n\ndeltaT          0.025;\n\nwriteControl    adjustableRunTime;\n\nwriteInterval   0.025;\n\npurgeWrite      0;\n\nwriteFormat     binary;\n\nwritePrecision  6;\n\nwriteCompression uncompressed;\n\ntimeFormat      general;\n\ntimePrecision   5;\n\nrunTimeModifiable true;\n\nadjustTimeStep  yes;\n\nmaxCo           0.9;\n\nmaxDeltaT       0.01;\n\nlibs            ( "libsolverFunctionObjects.so" );\n\nfunctions\n{\n    passiveScalar\n    {\n        type            scalarTransport;\n        writeControl    outputTime;\n        field           S;\n        diffusivity     viscosity;\n        alphal          1;\n        alphat          1;\n        autoSchemes     true;\n        nCorr           0;\n        resetOnStartUp  false;\n    }\n    #includeFunc    residuals\n}\n\n\n// ************************************************************************* //\n',
    'system/createBafflesDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      createBafflesDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ninternalFacesOnly true;\n\nbaffles\n{\n    baffleFaces\n    {\n        type        faceZone;\n        zoneName    interface;\n\n        patches\n        {\n            master\n            {\n                name            AMI1;\n                type            patch;\n            }\n            slave\n            {\n                name            AMI2;\n                type            patch;\n            }\n        }\n    }\n}\n\n// ************************************************************************* //\n',
    'system/decomposeParDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      decomposeParDict;\n}\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nnumberOfSubdomains 4;\n\nmethod          simple;\n\nsimpleCoeffs\n{\n    n               (2 2 1);\n    delta           0.001;\n}\n\n\n// ************************************************************************* //\n',
    'system/extrudeMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      extrudeMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// What to extrude:\n//      patch   : from patch of another case (\'sourceCase\')\n//      mesh    : as above but with original case included\n//      surface : from externally read surface\n\nconstructFrom patch;\nsourceCase ".";\nsourcePatches (front);\n\n// If construct from patch: patch to use for back (can be same as sourcePatch)\nexposedPatchName back;\n\n// Flip surface normals before usage. Valid only for extrude from surface or\n// patch.\nflipNormals false;\n\n//- Linear extrusion in point-normal direction\nextrudeModel        linearNormal;\n\nnLayers             1;\n\nexpansionRatio      1.0;\n\nlinearNormalCoeffs\n{\n    thickness       0.005;\n}\n\n// Do front and back need to be merged? Usually only makes sense for 360\n// degree wedges.\nmergeFaces false;   //true;\n\n// Merge small edges. Fraction of bounding box.\nmergeTol 0;\n\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default         Euler;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n    grad(p)         Gauss linear;\n    grad(U)         cellLimited Gauss linear 1;\n}\n\ndivSchemes\n{\n    default         none;\n    div(phi,U)      Gauss linearUpwindV grad(U);\n    div(phi,S)      Gauss linearUpwind grad(S);\n\n    div((nuEff*dev2(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear corrected;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         corrected;\n}\n\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    "pcorr.*"\n    {\n        solver          GAMG;\n        tolerance       1e-2;\n        relTol          0;\n        smoother        DICGaussSeidel;\n        cacheAgglomeration no;\n        maxIter         50;\n    }\n\n    p\n    {\n        $pcorr;\n        tolerance       1e-5;\n        relTol          0.01;\n    }\n\n    pFinal\n    {\n        $p;\n        tolerance       1e-6;\n        relTol          0;\n    }\n\n    MeshPhi\n    {\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-2;\n        relTol          0;\n    }\n\n    "(U|S)"\n    {\n        solver          PBiCGStab;\n        preconditioner  DILU;\n        tolerance       1e-6;\n        relTol          0.1;\n    }\n\n    "(U|S)Final"\n    {\n        $U\n        relTol          0;\n    }\n}\n\nPIMPLE\n{\n    //- Due to nOuterCorr = 1 --> PISO algorihm\n    nOuterCorrectors    1;\n    nCorrectors         2;      // Pressure correction equation two times\n    nNonOrthogonalCorrectors 0; \n    momentumPredictor   false;\n\n    correctMeshPhi      true;\n    correctPhi          true;\n}\n\n\n// ************************************************************************* //\n',
    'system/meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Include defaults parameters from master dictionary\n#includeEtc "caseDicts/mesh/generation/meshQualityDict"\n\nminVol 1e-8;\n\n// ************************************************************************* //\n',
    'system/snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      snappyHexMeshDict;\n}\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Which of the steps to run\ncastellatedMesh true;\nsnap            true;\naddLayers       false;\n\n\n// Geometry. Definition of all surfaces. All surfaces are of class\n// searchableSurface.\n// Surfaces are used\n// - to specify refinement for any mesh cell intersecting it\n// - to specify refinement for any mesh cell inside/outside/near\n// - to \'snap\' the mesh boundary to the surface\ngeometry\n{\n    regionSTL\n    {\n        file "regionSTL.stl";\n        type triSurfaceMesh;\n        regions\n        {\n            inlet           { name inlet;}\n\n            innerWall       { name innerWall; }\n            outerWall       { name outerWall; }\n            pipe            { name pipe; }\n            outlet          { name outlet; }\n            front           { name front; }\n            back            { name back; }\n        }\n    }\n\n    AMI\n    {\n        file "AMI.stl";\n        type triSurfaceMesh;\n        name AMI;\n    }\n\n    refine\n    {\n        file "refine.stl";\n        type triSurfaceMesh;\n        name refine;\n    }\n};\n\n\n\n// Settings for the castellatedMesh generation.\ncastellatedMeshControls\n{\n\n    // Refinement parameters\n    // ~~~~~~~~~~~~~~~~~~~~~\n\n    // If local number of cells is >= maxLocalCells on any processor\n    // switches from from refinement followed by balancing\n    // (current method) to (weighted) balancing before refinement.\n    maxLocalCells 2000000;\n\n    // Overall cell limit (approximately). Refinement will stop immediately\n    // upon reaching this number so a refinement level might not complete.\n    // Note that this is the number of cells before removing the part which\n    // is not \'visible\' from the keepPoint. The final number of cells might\n    // actually be a lot less.\n    maxGlobalCells 8000000;\n\n    // The surface refinement loop might spend lots of iterations refining just a\n    // few cells. This setting will cause refinement to stop if <= minimumRefine\n    // are selected for refinement. Note: it will at least do one iteration\n    // (unless the number of cells to refine is 0)\n    minRefinementCells 10;\n\n    // Number of buffer layers between different levels.\n    // 1 means normal 2:1 refinement restriction, larger means slower\n    // refinement.\n    nCellsBetweenLevels 3;\n\n\n\n    // Explicit feature edge refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies a level for any cell intersected by its edges.\n    // This is a featureEdgeMesh, read from constant/triSurface for now.\n    features\n    (\n    );\n\n\n\n    // Surface based refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies two levels for every surface. The first is the minimum level,\n    // every cell intersecting a surface gets refined up to the minimum level.\n    // The second level is the maximum level. Cells that \'see\' multiple\n    // intersections where the intersections make an\n    // angle > resolveFeatureAngle get refined up to the maximum level.\n\n    refinementSurfaces\n    {\n        regionSTL\n        {\n            level (0 0);\n            regions\n            {\n                inlet           { level (3 3); patchInfo { type patch; }}\n                outlet          { level (0 0); patchInfo { type patch; }}\n\n                front           { level (0 0); patchInfo { type wall; }}\n                back            { level (0 0); patchInfo { type wall; }}\n                innerWall       { level (3 3); patchInfo { type wall; }}\n                outerWall       { level (0 0); patchInfo { type wall; }}\n                pipe            { level (3 3); patchInfo { type wall; }}\n\n            }\n        }\n\n        AMI\n        {\n            level (0 0);\n\n            cellZone innerAMI;\n            faceZone innerAMI;\n            cellZoneInside inside;\n        }\n    }\n\n    resolveFeatureAngle 54;\n\n\n    // Region-wise refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies refinement level for cells in relation to a surface. One of\n    // three modes\n    // - distance. \'levels\' specifies per distance to the surface the\n    //   wanted refinement level. The distances need to be specified in\n    //   descending order.\n    // - inside. \'levels\' is only one entry and only the level is used. All\n    //   cells inside the surface get refined up to the level. The surface\n    //   needs to be closed for this to be possible.\n    // - outside. Same but cells outside.\n\n    refinementRegions\n    {\n        refine\n        {\n            mode inside;\n            levels ((0 2));\n        }\n    }\n\n\n    // Mesh selection\n    // ~~~~~~~~~~~~~~\n\n    // After refinement patches get added for all refinementSurfaces and\n    // all cells intersecting the surfaces get put into these patches. The\n    // section reachable from the locationInMesh is kept.\n    // NOTE: This point should never be on a face, always inside a cell, even\n    // after refinement.\n    // This is an outside point locationInMesh (-0.033 -0.033 0.0033);\n    locationInMesh (0.02 0.02 0.001); // Inside point\n\n    // Whether any faceZones (as specified in the refinementSurfaces)\n    // are only on the boundary of corresponding cellZones or also allow\n    // free-standing zone faces. Not used if there are no faceZones.\n    allowFreeStandingZoneFaces true;\n}\n\n\n\n// Settings for the snapping.\nsnapControls\n{\n    //- Number of patch smoothing iterations before finding correspondence\n    //  to surface\n    nSmoothPatch 2;\n\n    //- Relative distance for points to be attracted by surface feature point\n    //  or edge. True distance is this factor times local\n    //  maximum edge length.\n    tolerance 1.2;\n\n    //- Number of mesh displacement relaxation iterations.\n    nSolveIter 100;\n\n    //- Maximum number of snapping relaxation iterations. Should stop\n    //  before upon reaching a correct mesh.\n    nRelaxIter 3;\n\n    // Feature snapping\n\n        //- Number of feature edge snapping iterations.\n        //  Leave out altogether to disable.\n        nFeatureSnapIter 4;\n\n        //- Detect (geometric) features by sampling the surface\n        implicitFeatureSnap true;\n\n        //- Use castellatedMeshControls::features\n        explicitFeatureSnap false;\n\n        //- Detect features between multiple surfaces\n        //  (only for explicitFeatureSnap, default = false)\n        multiRegionFeatureSnap false;\n}\n\n\n\n// Settings for the layer addition.\naddLayersControls\n{\n    // Are the thickness parameters below relative to the undistorted\n    // size of the refined cell outside layer (true) or absolute sizes (false).\n    relativeSizes false;\n\n    // Per final patch (so not geometry!) the layer information\n    layers\n    {\n    }\n\n    expansionRatio 1.2;\n    thickness 0.008;\n    minThickness 0.00001;\n\n    // If points get not extruded do nGrow layers of connected faces that are\n    // also not grown. This helps convergence of the layer addition process\n    // close to features.\n    nGrow 0; // Should be 0, otherwise layers are colapsed\n\n\n    // Advanced settings\n\n    // When not to extrude surface. 0 is flat surface, 90 is when two faces\n    // are perpendicular\n    featureAngle 75; // > 60 grad provides good match near the 90 grad corners\n\n    // Maximum number of snapping relaxation iterations. Should stop\n    // before upon reaching a correct mesh.\n    nRelaxIter 8;// 3;\n\n    // Number of smoothing iterations of surface normals\n    nSmoothSurfaceNormals 6;//1;\n\n    // Number of smoothing iterations of interior mesh movement direction\n    nSmoothNormals 8;//3;\n\n    // Smooth layer thickness over surface patches\n    nSmoothThickness 10;\n\n    // Stop layer growth on highly warped cells\n    maxFaceThicknessRatio 0.8;//0.5;\n\n    // Reduce layer growth where ratio thickness to medial\n    // distance is large\n    maxThicknessToMedialRatio 0.6;//0.3;\n\n    // Angle used to pick up medial axis points\n    minMedianAxisAngle 90;\n    nMedialAxisIter 4;\n\n    // Create buffer region for new layer terminations\n    nBufferCellsNoExtrude 0;\n\n\n    // Overall max number of layer addition iterations. The mesher will exit\n    // if it reaches this number of iterations; possibly with an illegal\n    // mesh.\n    nLayerIter 50;\n\n    // Max number of iterations after which relaxed meshQuality controls\n    // get used. Up to nRelaxIter it uses the settings in meshQualityControls,\n    // after nRelaxIter it uses the values in meshQualityControls::relaxed.\n    nRelaxedIter 20;\n}\n\n\n\n// Generic mesh quality settings. At any undoable phase these determine\n// where to undo.\nmeshQualityControls\n{\n    #include "meshQualityDict"\n\n    // Optional : some meshing phases allow usage of relaxed rules.\n    // See e.g. addLayersControls::nRelaxedIter.\n    relaxed\n    {\n        //- Maximum non-orthogonality allowed. Set to 180 to disable.\n        maxNonOrtho 180;\n    }\n\n    // Advanced\n\n    //- Number of error distribution iterations\n    nSmoothScale 4;\n    //- amount to scale back displacement at error points\n    errorReduction 0.75;\n}\n\n\n// Advanced\n\n// Write flags\nwriteFlags\n(\n    scalarLevels    // write volScalarField with cellLevel for postprocessing\n    layerSets       // write cellSets, faceSets of faces in layer\n    layerFields     // write volScalarField for layer coverage\n);\n\n\n// Merge tolerance. Is fraction of overall bounding box of initial mesh.\n// Note: the write tolerance needs to be higher than this.\nmergeTolerance 1E-6;\n\n\n// ************************************************************************* //\n',
    'system/topoSetDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    object      topoSetDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nactions\n(\n    // Create the interface faceZone\n    {\n        name        interface;\n        action      new;\n        type        faceZoneSet;\n\n        source      searchableSurfaceToFaceZone;\n        surface     closedTriSurfaceMesh;\n        file        "AMI.stl";\n    }\n\n    // Create the rotating cellZone\n    {\n        name        rotatingCells;\n        action      new;\n        type        cellZoneSet;\n\n        source      cylinderToCell;\n        point1      (0 0 0);\n        point2      (0 0 1);\n        radius      0.22;\n    }\n);\n\n\n// ************************************************************************* //\n',
}
